// === Tab: tab2 ===
class Birb{

   constructor(A, w, h, tau, i, j, latice, cl, cr) {
     this.A = A;
     this.Ax = this.A.x;
     this.Ay = this.A.y;
     this.w = w; 
		 this.h = h;

		 this.ho = this.h;  //if this value is 0 or any other small number kiwis becom creatures
		 										//this.ho = 9;
     this.tau = tau;
     this.i = i;
     this.j = j;
     this.latice =latice;
     this.cl = cl;
     this.cr = cr;

     this.t = random(1000);
   }

   display_new02(){
      push();
      translate(this.A.x, this.A.y);
      let tau_c = this.w*this.tau*0.5;
      let f = (this.w+this.h)/30;
		  let g = f*0.45;

		 //even columns are facing -1 direction
      let d=1;
      if (this.i%2===1) {d=-1;}

       for(let k=0; k<this.latice; k++){
         lingrad = drawingContext.createLinearGradient( 0+( k*50),  -this.h+( k*50)  , this.w ,  1.25*this.h );
         lingrad.addColorStop(0, this.cr);
         lingrad.addColorStop(1, this.cl);
         drawingContext.fillStyle = lingrad;

        stroke(0); strokeWeight(0.1);
         beginShape();
            vertex(d*k*f, this.h*0.25);
            bezierVertex(d*k*f, this.h*0.25-tau_c, d*(this.w*0.66-tau_c*1.5), -this.h*0.5,   d*this.w*0.66, -this.h*0.5);
            vertex(d*this.w*1.2, -this.h*0.5);
            bezierVertex(d*this.w, -this.h*0.5, d*this.w*0.75, -this.h*0.25-tau_c/2,    d*this.w*0.75, -this.h*0.25);
            bezierVertex(d*this.w*0.75, -this.h*0.25+tau_c/2, d*this.w, this.h*0.25-tau_c,  d*this.w, this.h*0.25);
            bezierVertex(d*this.w, this.h*0.25+tau_c-k*g,  d*(this.w*0.5+tau_c-k*g) , this.h*0.75-k*f,  d*this.w*0.5, this.h*0.75-k*f);
            bezierVertex(d*(this.w*0.5-tau_c+k*g) , this.h*0.75-k*f,  d*k*f, this.h*0.25+tau_c-k*g, d*k*f, this.h*0.25);
         endShape( );

      }

		 //legs
      line(d*this.w/2+10, this.h*0.68, d*this.w/2+10, this.h*0.68+this.h/4);
      for (let i=0;i<3; i++){
         line(d*this.w/2+10, this.h*0.68+this.h/4,  cos(1.5*(d-1)+(1-i)*0.4)*10 + d*this.w/2+10, sin(1.5*(d-1)+ (1-i)*0.4)*10 + this.h*0.68+this.h/4);
      }
      line(d*this.w/2-10, this.h*0.75, d*this.w/2-10, this.h*0.68+this.h/5);
      for (let i=0;i<3; i++){
         line(d*this.w/2-10, this.h*0.68+this.h/5,  cos(1.5*(d-1)+(1-i)*0.4)*10 + d*this.w/2-10, sin(1.5*(d-1)+ (1-i)*0.4)*10 + this.h*0.68+this.h/5);
      }


		  //eyes
      fill(255);  
      ellipse(d*this.w*0.7, -this.h*0.4, 15, 15);
      fill(0); noStroke();
      ellipse(d*(this.w*0.7+3), -this.h*0.4, 5, 5);
      pop();
   }

   move(){
      this.h = this.ho + sin(this.t+PI)*10;
      this.A.y = this.Ay + + sin(this.t)*10;      
      this.t+=0.15;
   }
}

